args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Return_to_Return_to_Nuke_'Em_High_AKA_Volume_2 dbr:Zameen_(2003_film) }

  OPTIONAL { ?film dbo:director ?d1 . }
  OPTIONAL { ?film dbp:director ?d2 . }
  BIND(coalesce(?d1, ?d2) AS ?director)
  FILTER(BOUND(?director))

  OPTIONAL { ?director dbo:birthDate ?bd1 . }
  OPTIONAL { ?director dbp:birthDate ?bd2 . }
  BIND(coalesce(?bd1, ?bd2) AS ?birthDate)

  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = 'en') }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = 'en') }
}

